//! The app's [`AssetSource`]: every file under `assets/`, embedded in the binary at build time (no runtime
//! file reads), then gpui-component's Lucide icons for its own widgets.
//!
//! Paths:
//! - `hugeicons/<name>.svg`: Hugeicons glyphs (`ui::Icon`), generated by `tools/gen-icons.mjs`. Each file is
//!   stroked at 1.8 in its 24-unit viewBox, the width DESIGN.md gives 14 and 16px icons. A path ending in
//!   `@<width>` (`hugeicons/search-01.svg@1.6`) serves the same file at another stroke width, so 12px (1.6)
//!   and 18px (2) icons match the desktop's `<Icon>` without a second file. GPUI caches each rendered
//!   path and size once.
//! - `logos/<provider>.svg` (brand colours, drawn with `img()`) and `logos/<provider>-mono.svg` (one path,
//!   drawn with `svg()` in the text colour).
//! - `ui/...`: hand-drawn shapes, such as the spinner ring.
//! - `icons/...`: gpui-component's bundle (`gpui_kit_assets::Assets`).
//!
//! To add a file, put it under `assets/` and run `node tools/gen-icons.mjs`, which rewrites the table in
//! `embedded.rs`.

use std::borrow::Cow;

use gpui::{AssetSource, Result, SharedString};

#[rustfmt::skip] // generated by tools/gen-icons.mjs
mod embedded;

#[cfg(test)]
mod tests;

/// The stroke width written into every generated icon file (see `tools/gen-icons.mjs`).
pub(crate) const FILE_STROKE: &str = "1.8";

/// Our embedded files first, then gpui-component's icons.
#[derive(Clone, Copy, Debug, Default)]
pub struct Assets;

impl Assets {
    /// The bytes of an embedded file, by its path under `assets/`.
    pub fn embedded(path: &str) -> Option<&'static [u8]> {
        embedded::FILES.binary_search_by_key(&path, |(name, _)| name).ok().map(|ix| embedded::FILES[ix].1)
    }

    /// Every embedded path, sorted.
    pub fn embedded_paths() -> impl Iterator<Item = &'static str> {
        embedded::FILES.iter().map(|(name, _)| *name)
    }
}

impl AssetSource for Assets {
    fn load(&self, path: &str) -> Result<Option<Cow<'static, [u8]>>> {
        let (file, stroke) = match path.rsplit_once('@') {
            Some((file, stroke)) if file.ends_with(".svg") => (file, Some(stroke)),
            _ => (path, None),
        };
        if let Some(bytes) = Self::embedded(file) {
            return Ok(Some(match stroke {
                None => Cow::Borrowed(bytes),
                Some(stroke) => Cow::Owned(with_stroke(bytes, stroke)?),
            }));
        }
        gpui_kit_assets::Assets.load(path)
    }

    fn list(&self, path: &str) -> Result<Vec<SharedString>> {
        let mut found: Vec<SharedString> = Self::embedded_paths().filter(|name| name.starts_with(path)).map(SharedString::from).collect();
        found.extend(gpui_kit_assets::Assets.list(path)?);
        Ok(found)
    }
}

/// The SVG with every `stroke-width="1.8"` set to `stroke` (a plain decimal such as `1.6` or `2`).
fn with_stroke(svg: &[u8], stroke: &str) -> Result<Vec<u8>> {
    anyhow::ensure!(
        !stroke.is_empty() && stroke.bytes().all(|b| b.is_ascii_digit() || b == b'.'),
        "a stroke width is a plain decimal, got {stroke:?}"
    );
    let text = std::str::from_utf8(svg)?;
    let from = format!("stroke-width=\"{FILE_STROKE}\"");
    Ok(text.replace(&from, &format!("stroke-width=\"{stroke}\"")).into_bytes())
}
